questionvariables.text:
stack_include_contrib("prooflib.mac");
proof_steps : [
 ["start",    "Start with the standard form \\(a x^2 + b x + c = 0\\), where \\(a \\neq 0\\)."],
 ["divide",   "Divide every term by \\(a\\): \\[ x^2 + \\frac{b}{a}x + \\frac{c}{a} = 0. \\]"],
 ["move",     "Move the constant term to the right-hand side: \\[ x^2 + \\frac{b}{a}x = -\\frac{c}{a}. \\]"],
 ["complete", "Add \\(\\left(\\frac{b}{2a}\\right)^2\\) to both sides: \\[ x^2 + \\frac{b}{a}x + \\left(\\frac{b}{2a}\\right)^2 = -\\frac{c}{a} + \\left(\\frac{b}{2a}\\right)^2. \\]"],
 ["factor",   "Write the left-hand side as a perfect square and combine the right over \\(4a^2\\): \\[ \\left(x+\\frac{b}{2a}\\right)^2 = \\frac{b^2-4ac}{4a^2}. \\]"],
 ["root",     "Take the square root of both sides: \\[ x + \\frac{b}{2a} = \\pm\\frac{\\sqrt{b^2-4ac}}{2a}. \\]"],
 ["isolate",  "Subtract \\(\\frac{b}{2a}\\) from both sides: \\[ x = -\\frac{b}{2a} \\pm \\frac{\\sqrt{b^2-4ac}}{2a}. \\]"],
 ["combine",  "Write the right-hand side as a single fraction: \\[ x = \\frac{-b\\pm\\sqrt{b^2-4ac}}{2a}. \\]"]
];
/* Shuffle only the ORDER shown to the student; the correct answer is fixed. */
proof_steps : random_permutation(proof_steps);
/* The teacher's answer: the correct sequence of step keys. */
ta : proof("start","divide","move","complete","factor","root","isolate","combine");
